insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Wild Grace Mobile Pet Spa','Pet Services','Service area only','','(209) 200-4014','https://wildgracepetspa.com/','Mobile dog grooming provider whose website explicitly lists Mountain House, Tracy, Lathrop and Manteca. Requests are followed up to confirm service and appointment time; submitting a request does not reserve an appointment. Confirm pet suitability, quote and availability directly. Street address not established.','approved',true,false,null,0,'editorial_first_party','https://wildgracepetspa.com/contact/','first_party_website_desk_check',now()) returning id into bid;
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://wildgracepetspa.com/contact/',array['identity','website','public phone','advertised services','advertised service area'],array['Mountain House','Tracy','Lathrop','Manteca'],array['mobile dog grooming','dog grooming'],'First-party website desk check of public phone, mobile grooming and four explicit service areas. Appointment request requires subsequent confirmation. No street address, independent credentials, insurance, quality or availability established; no images reused. Sources: https://wildgracepetspa.com/contact/ https://wildgracepetspa.com/about-us/');
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name":"Wild Grace Mobile Pet Spa","website":"https://wildgracepetspa.com/","phone":"(209) 200-4014","sources":["https://wildgracepetspa.com/contact/","https://wildgracepetspa.com/about-us/"],"description":"Mobile dog grooming provider whose website explicitly lists Mountain House, Tracy, Lathrop and Manteca. Requests are followed up to confirm service and appointment time; submitting a request does not reserve an appointment. Confirm pet suitability, quote and availability directly. Street address not established."}'::jsonb,'First-party website desk check; no owner confirmation','https://wildgracepetspa.com/contact/');
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status) select 'Family BINGO — November 17','The library invites families of all ages to play BINGO. This entry covers November 17 only. Date, time and branch checked against official sources; confirm attendance details with the library.','Mountain House','Mountain House Branch Library, 201 E Main Street, Mountain House','2026-11-17T15:30:00-08:00','2026-11-17T16:30:00-08:00','Community programs','https://www.ssjcpl.org/events-services/events-calendar/mountain-house/family-bingo4?id=1794958200-246965','HIGH','approved','editorial_community_2026',0.95,false,'approved' where not exists(select 1 from public.events where city='Mountain House' and source_url='https://www.ssjcpl.org/events-services/events-calendar/mountain-house/family-bingo4?id=1794958200-246965' and start_date='2026-11-17T15:30:00-08:00'::timestamptz);
